CREATE TABLE IF NOT EXISTS document_metadata_enrichments (
  document_id INTEGER PRIMARY KEY REFERENCES documents(id),
  original_payload_json TEXT CHECK(original_payload_json IS NULL OR (length(original_payload_json) BETWEEN 2 AND 1048576 AND json_valid(original_payload_json))),
  original_payload_sha256 TEXT CHECK(original_payload_sha256 IS NULL OR (length(original_payload_sha256)=64 AND original_payload_sha256 NOT GLOB '*[^0-9a-fA-F]*')),
  enriched_metadata_json TEXT NOT NULL CHECK(length(enriched_metadata_json) BETWEEN 2 AND 1048576 AND json_valid(enriched_metadata_json)),
  enriched_metadata_sha256 TEXT NOT NULL CHECK(length(enriched_metadata_sha256)=64 AND enriched_metadata_sha256 NOT GLOB '*[^0-9a-fA-F]*'),
  actor TEXT NOT NULL CHECK(length(trim(actor)) BETWEEN 1 AND 256),
  program TEXT NOT NULL CHECK(length(trim(program)) BETWEEN 1 AND 256),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK((original_payload_json IS NULL AND original_payload_sha256 IS NULL) OR (original_payload_json IS NOT NULL AND original_payload_sha256 IS NOT NULL))
);
CREATE TRIGGER document_metadata_enrichments_no_update BEFORE UPDATE ON document_metadata_enrichments BEGIN SELECT RAISE(ABORT, 'document metadata enrichments are append-only'); END;
CREATE TRIGGER document_metadata_enrichments_no_delete BEFORE DELETE ON document_metadata_enrichments BEGIN SELECT RAISE(ABORT, 'document metadata enrichments are append-only'); END;
